// Takes whichever agent answered. If every AI model is out of free quota, say so honestly
// and flag 'limited' so the website stops the voice loop and uses the browser's own voice.
const out = $input.first().json;
let text = String(out.output ?? out.text ?? '').trim();
text = text.replace(/\*\*?|__|`+|^#+\s*/gm, '').replace(/^\s*[-*]\s+/gm, '').replace(/\s+\n/g, '\n').trim();
let limited = false;
if (!text) {
  limited = true;
  text = "I'm getting more visitors than I can answer right now, so please try me again in a little while. You can also call my demo line at +1 (629) 205-4731 or sign up with the form on this page.";
}
// Remember Sara's real replies for 15 minutes; the voice endpoint will only speak these.
if (!limited) {
  const sd = $getWorkflowStaticData('global');
  const now = Date.now();
  sd.recentReplies = (sd.recentReplies || []).filter(function (r) { return now - r.t < 15 * 60000; }).slice(-300);
  sd.recentReplies.push({ t: now, text: text.replace(/\s+/g, ' ').trim().toLowerCase() });
}
const prep = $('Prepare Turn').first().json;
return [{ json: { reply: text, voice: prep.voice, limited: limited } }];

// Spending guard for Sara's website chat.
// Each visitor (by IP, or by chat session if no IP is passed on) gets a per-hour and per-day allowance,
// with a total cap per day, so nobody can run up the AI bill. Counters live in this workflow's static data.
const req = $input.first().json;
const h = req.headers || {};
const ip = String(h['cf-connecting-ip'] || h['x-real-ip'] || String(h['x-forwarded-for'] || '').split(',')[0] || '').trim();
const session = String(req.body?.session_id ?? '').replace(/[^a-zA-Z0-9-]/g, '').slice(0, 40);
const who = ip ? 'ip:' + ip : 'session:' + (session || 'none');
const PER_VISITOR_PER_HOUR = 15;
const PER_VISITOR_PER_DAY = 40;
const PER_DAY = 600;
const sd = $getWorkflowStaticData('global');
const hour = Math.floor(Date.now() / 3600000);
const day = new Date().toISOString().slice(0, 10);
sd.guard = sd.guard || {};
let g = sd.guard['chat'] || {};
if (g.hour !== hour) { g.hour = hour; g.ips = {}; }
if (g.day !== day) { g.day = day; g.dayCount = 0; g.dayIps = {}; }
g.dayIps = g.dayIps || {};
let reason = '';
if (!String(req.body?.message ?? '').trim()) reason = 'empty';
if (!reason && (g.ips[who] || 0) >= PER_VISITOR_PER_HOUR) reason = 'visitor';
if (!reason && (g.dayIps[who] || 0) >= PER_VISITOR_PER_DAY) reason = 'visitor_day';
if (!reason && (g.dayCount || 0) >= PER_DAY) reason = 'day';
if (!reason) { g.ips[who] = (g.ips[who] || 0) + 1; g.dayIps[who] = (g.dayIps[who] || 0) + 1; g.dayCount = (g.dayCount || 0) + 1; }
sd.guard['chat'] = g;
return [{ json: { ...req, allowed: !reason, limit_reason: reason, visitor: ip ? 'ip' : 'session', visitor_count_this_hour: g.ips[who] || 0, visitor_count_today: g.dayIps[who] || 0, count_today: g.dayCount } }];

// Spending and abuse guard for Sara's website voice.
// 1) It only speaks text Sara herself replied in the last 15 minutes, so nobody can use it as a free text-to-speech service.
// 2) Each visitor gets a per-hour and per-day allowance, plus a total cap per day.
const req = $input.first().json;
const h = req.headers || {};
const ip = String(h['cf-connecting-ip'] || h['x-real-ip'] || String(h['x-forwarded-for'] || '').split(',')[0] || '').trim();
const session = String(req.body?.session_id ?? '').replace(/[^a-zA-Z0-9-]/g, '').slice(0, 40);
const who = ip ? 'ip:' + ip : 'session:' + (session || 'none');
const PER_VISITOR_PER_HOUR = 40;
const PER_VISITOR_PER_DAY = 100;
const PER_DAY = 1500;
const norm = function (s) { return String(s || '').replace(/\s+/g, ' ').trim().toLowerCase(); };
const text = norm(req.body?.text);
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const recent = (sd.recentReplies || []).filter(function (r) { return now - r.t < 15 * 60000; });
const hour = Math.floor(now / 3600000);
const day = new Date().toISOString().slice(0, 10);
sd.guard = sd.guard || {};
let g = sd.guard['voice'] || {};
if (g.hour !== hour) { g.hour = hour; g.ips = {}; }
if (g.day !== day) { g.day = day; g.dayCount = 0; g.dayIps = {}; }
g.dayIps = g.dayIps || {};
let reason = '';
if (!text) reason = 'empty';
if (!reason && !recent.some(function (r) { return r.text.indexOf(text) >= 0; })) reason = 'not_sara';
if (!reason && (g.ips[who] || 0) >= PER_VISITOR_PER_HOUR) reason = 'visitor';
if (!reason && (g.dayIps[who] || 0) >= PER_VISITOR_PER_DAY) reason = 'visitor_day';
if (!reason && (g.dayCount || 0) >= PER_DAY) reason = 'day';
if (!reason) { g.ips[who] = (g.ips[who] || 0) + 1; g.dayIps[who] = (g.dayIps[who] || 0) + 1; g.dayCount = (g.dayCount || 0) + 1; }
sd.guard['voice'] = g;
return [{ json: { ...req, allowed: !reason, limit_reason: reason, visitor: ip ? 'ip' : 'session', visitor_count_this_hour: g.ips[who] || 0, count_today: g.dayCount } }];

